INSERT INTO public.marketing_content_items (title, kind, channel, brief, status, publish_at, metadata)
SELECT b.title, 'blog', 'blog', b.excerpt, 'published', b.published_at::timestamptz,
  jsonb_build_object('slug', b.slug, 'category', b.category, 'source', 'blog_posts', 'url', '/blog/' || b.slug, 'tags', to_jsonb(b.tags))
FROM public.blog_posts b
WHERE b.published AND b.slug NOT LIKE 'seed-blog_posts-%'
  AND NOT EXISTS (SELECT 1 FROM public.marketing_content_items c WHERE c.kind='blog' AND c.metadata->>'slug' = b.slug);

DELETE FROM public.marketing_aeo_questions WHERE metadata->>'seed' = 'blog_aeo_v1';
INSERT INTO public.marketing_aeo_questions (question, answer, entity, source_path, pattern, status, clarity_score, last_reviewed, metadata)
SELECT 'How does Bubaly help with ' || lower(p.title) || '?',
  p.excerpt || ' Bubaly — the AI Family Operating System — turns this into shared, automatic routines your whole family can see. Read the full guide at /blog/' || p.slug || '.',
  'Bubaly', '/blog/' || p.slug, 'faq', 'published', 88, now(),
  jsonb_build_object('seed','blog_aeo_v1','slug',p.slug,'category',p.category,'article',true)
FROM public.blog_posts p WHERE p.published AND p.slug NOT LIKE 'seed-blog_posts-%'
UNION ALL
SELECT p.title || ' — where should a family start?',
  'Start small and let the system do the remembering. ' || p.excerpt || ' Bubaly — the AI Family Operating System — keeps the whole family in sync. Full guide: /blog/' || p.slug || '.',
